Branching DDL ​ CREATE audit branch at the latest snapshot with default retention
ALTER TABLE iceberg_demo_db . employees CREATE BRANCH audit ;
CREATE audit branch at snapshot 1234 with default retention.
ALTER TABLE iceberg_demo_db . employees CREATE BRANCH audit
AS OF VERSION 1234 ;
